import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    BoxGeometry,
    PlaneGeometry,
    Color,
    DirectionalLight,
    PointLight,
    Box3,
    Vector3,
  } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'home-thumbnail-card';

  const cardGroup = new Group();
  cardGroup.name = 'home-thumbnail-card-inner';
  root.add(cardGroup);

  const disposables = [];
  const tweens = [];

  // ---- dimensions ----
  const cardWidth = 1.7;
  const cardHeight = 1.05;
  const captionHeight = 0.3;
  const imageHeight = cardHeight - captionHeight - 0.05;

  const captionY = -(cardHeight / 2) + captionHeight / 2;
  const imageY = cardHeight / 2 - imageHeight / 2 - 0.02;

  // ---- accent edge frame (behind backing, peeks out as a thin border) ----
  const edgeStrength = uniform(0.12);
  const edgeGeo = new BoxGeometry(cardWidth + 0.04, cardHeight + 0.04, 0.02);
  const edgeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.5,
    metalness: 0.3,
  });
  edgeMat.emissiveNode = vec3(
    new Color(colors.accent).r,
    new Color(colors.accent).g,
    new Color(colors.accent).b
  ).mul(edgeStrength);
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, 0, -0.025);
  cardGroup.add(edgeMesh);
  disposables.push(edgeGeo, edgeMat);

  // ---- backing plate (machined metal card body) ----
  const backingGeo = new BoxGeometry(cardWidth, cardHeight, 0.08);
  const backingMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.35,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  const backingMesh = new Mesh(backingGeo, backingMat);
  backingMesh.position.set(0, 0, 0);
  cardGroup.add(backingMesh);
  disposables.push(backingGeo, backingMat);

  // ---- image placeholder area ----
  const imageAreaGeo = new BoxGeometry(cardWidth - 0.2, imageHeight, 0.02);
  const imageAreaMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.6,
    metalness: 0.15,
  });
  const imageAreaMesh = new Mesh(imageAreaGeo, imageAreaMat);
  imageAreaMesh.position.set(0, imageY, 0.045);
  cardGroup.add(imageAreaMesh);
  disposables.push(imageAreaGeo, imageAreaMat);

  // ---- caption strip ----
  const captionGeo = new BoxGeometry(cardWidth - 0.2, captionHeight - 0.06, 0.03);
  const captionMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.55,
    metalness: 0.25,
  });
  const captionMesh = new Mesh(captionGeo, captionMat);
  captionMesh.position.set(0, captionY, 0.045);
  cardGroup.add(captionMesh);
  disposables.push(captionGeo, captionMat);

  // small accent tick on caption strip to mark it as a live card control
  const tickGeo = new BoxGeometry(0.22, 0.03, 0.02);
  const tickMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.5,
    metalness: 0.2,
  });
  const tickMesh = new Mesh(tickGeo, tickMat);
  tickMesh.position.set(-(cardWidth - 0.2) / 2 + 0.2, captionY, 0.07);
  cardGroup.add(tickMesh);
  disposables.push(tickGeo, tickMat);

  // ---- contact shadow (soft radial, behind card) ----
  const shadowGeo = new PlaneGeometry(cardWidth * 1.4, cardHeight * 1.4);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const centeredUv = uv().sub(vec2(0.5, 0.5));
  const dist = centeredUv.length();
  const alphaNode = smoothstep(0.5, 0.0, dist).mul(0.45);
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = alphaNode;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.05, -0.08);
  cardGroup.add(shadowMesh);
  disposables.push(shadowGeo, shadowMat);

  // ---- local lighting: rim + accent kicker (scene supplies ambient 0.6 + key 1.2) ----
  const rimLight = new DirectionalLight(new Color(colors.paper), 0.75);
  rimLight.position.set(-1.2, 1.0, 1.4);
  cardGroup.add(rimLight);

  const accentKicker = new PointLight(new Color(colors.accent), 0.5, 2.2);
  accentKicker.position.set(0.6, -0.5, 0.6);
  cardGroup.add(accentKicker);

  // ---- gear mesh (mesh render mode) ----
  let gearRoot = null;
  const meshUrl = config.meshUrl;

  ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
    const scene = gltf.scene ?? (gltf.scenes && gltf.scenes[0]);
    if (!scene) return;
    gearRoot = scene;

    const box = new Box3().setFromObject(gearRoot);
    const size = new Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y, size.z, 0.0001);
    const targetSize = Math.min(cardWidth - 0.4, imageHeight - 0.1);
    const scale = targetSize / maxDim;
    gearRoot.scale.setScalar(scale);

    const center = new Vector3();
    box.getCenter(center);
    gearRoot.position.set(
      -center.x * scale,
      imageY - center.y * scale,
      0.09 - center.z * scale
    );

    cardGroup.add(gearRoot);
  }).catch(() => {});

  // ---- interactions ----
  const baseScale = 1;
  let hovered = false;

  const doHoverIn = () => {
    if (hovered) return;
    hovered = true;
    const tl = gsap.to(cardGroup.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    const tl2 = gsap.to(edgeStrength, {
      value: 1.0,
      duration: 0.3,
      ease: 'power2.out',
    });
    tweens.push(tl, tl2);
  };

  const doHoverOut = () => {
    hovered = false;
    const tl = gsap.to(cardGroup.position, {
      y: 0,
      duration: 0.6,
      ease: 'power2.out',
    });
    const tl2 = gsap.to(edgeStrength, {
      value: 0.12,
      duration: 0.3,
      ease: 'power2.out',
    });
    tweens.push(tl, tl2);
  };

  const doPress = () => {
    const tl = gsap.to(cardGroup.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
    tweens.push(tl);
  };

  const doRelease = () => {
    const tl = gsap.to(cardGroup.scale, {
      x: baseScale,
      y: baseScale,
      z: baseScale,
      duration: 0.35,
      ease: 'power2.out',
    });
    tweens.push(tl);
  };

  const doClick = () => {
    doPress();
    gsap.delayedCall(0.14, doRelease);
    ctx.emit('hub-home.select', { source: 'home-thumbnail-card' });
  };

  root.userData.handlers = {
    onPointerOver: doHoverIn,
    onPointerEnter: doHoverIn,
    hover: doHoverIn,
    onPointerOut: doHoverOut,
    onPointerLeave: doHoverOut,
    unhover: doHoverOut,
    onPointerDown: doPress,
    onPointerUp: doRelease,
    onClick: doClick,
    click: doClick,
  };

  root.userData.cleanup = () => {
    tweens.forEach((t) => t && t.kill && t.kill());
    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.scale);
    gsap.killTweensOf(edgeStrength);

    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });

    if (gearRoot) {
      gearRoot.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => {
            if (m.map) m.map.dispose();
            m.dispose();
          });
        }
      });
    }

    cardGroup.clear();
    root.clear();
  };

  return root;
}
